/* Admin: home page carousel editor */
(function(){var ST=window.ST,BA=ST&&ST.BA;if(!ST||!window.BA_CAR)return;var esc=ST.esc,$=ST.$;
var LINKS=[['search.html','Search all auctions'],['premium.html','Premium properties'],['pricing.html','Plans and pricing'],['lawyers.html','Talk to a lawyer'],['concierge.html','Concierge'],['nri-services.html','NRI services'],['learn.html','Learn'],['data.html','How we decode data'],['faq.html','FAQ'],['residential-properties.html','Residential'],['commercial-properties.html','Commercial'],['industrial-properties.html','Industrial'],['agricultural-properties.html','Agricultural']];
function ov(){return BA.jget('ba3_car',{})||{}}
function checks(id){var p=BA.find(id);if(!p)return {err:'No property with this reference.',rows:[]};var fv=BA.jget('ba3_fv',{})[id],un=BA.jget('ba3_unpub',[]).indexOf(id)>-1,R=[];
 function add(ok,txt,hard){R.push({ok:ok,txt:txt,hard:!!hard})}
 add(!un,'Live on the site (not unpublished)',1);add(p.days>=3,'At least 3 days to the auction ('+p.days+' days left)',1);add(p.days>=7,'7 days or more to the auction, so visitors have time to act');
 add(!!fv||!!p.exception,'Latest verified site visit photographs and videos are available');add(p.bank_photos>0||(p.bankimgs||[]).length>0||!!fv,'Has real photographs, not placeholders');
 add(p.disc>=10,'At least 10% below market value ('+p.disc+'%)');add(p.score>=70,'AI score of 70 or more ('+p.score+')');add(!p.premium,'Not a Premium property (Premium details stay locked until paid)');
 return {p:p,rows:R,hard:R.some(function(r){return r.hard&&!r.ok}),warn:R.some(function(r){return !r.hard&&!r.ok})}}
function chkHtml(id){var c=checks(id);if(c.err)return '<div class="ok" style="background:#FFE9EE;color:#9B1C47">'+c.err+'</div>';return '<div style="font-size:13px;margin-top:6px"><b>'+esc(c.p.short)+', '+esc(c.p.loc)+'</b> · '+esc(BA.D.cities[c.p.city].label)+' · reserve '+BA.inr(c.p.reserve)+'<ul style="list-style:none;padding:0;margin:6px 0 0">'+c.rows.map(function(r){return '<li style="color:'+(r.ok?'#0B5D57':r.hard?'#A50E0E':'#8A5A00')+'">'+(r.ok?'✓ ':r.hard?'✕ ':'! ')+esc(r.txt)+'</li>'}).join('')+'</ul></div>'}
function img(file,cb){if(!/^image\/(jpeg|png|webp)$/.test(file.type)){BA.toast('Use a JPG, PNG or WebP picture');return}var u=URL.createObjectURL(file),im=new Image();im.onload=function(){var W=1200,H=380,c=document.createElement('canvas');c.width=W;c.height=H;var x=c.getContext('2d'),r=Math.max(W/im.width,H/im.height),w=im.width*r,h=im.height*r;x.drawImage(im,(W-w)/2,(H-h)/2,w,h);URL.revokeObjectURL(u);cb(c.toDataURL('image/jpeg',.82))};im.onerror=function(){BA.toast('Could not read that picture')};im.src=u}
window.ADM_CAR=function(tb){var O=ov();
 tb.innerHTML=ST.panel('Home page carousel',
 '<p style="margin:0 0 10px;color:var(--mute)">Ten slides sit right under the header on the home page and move left to right every 10 seconds. Each slide has a picture, the problem and how BankAuctions.ai solves it. Change the wording, replace a picture, hide a slide, or feature one property.</p><div class="tip"><b>Guidance for choosing pictures</b><ul><li>Upload a wide picture. It is cropped to a wide banner about 3 : 1 (1600 × 506 works well). Keep faces and key objects near the centre.</li><li>Show Indian buyers, families, NRIs or bank customers in natural settings. Use photos you own or have licensed, with consent from anyone clearly identifiable. No bank logos, no real customer names or documents.</li><li>The default pictures are photographs of South Indian cities, homes and offices. A replacement works best if it shows one clear scene; the problem and solution text sit below it.</li><li>JPG, PNG or WebP. The picture is compressed and kept in this browser in the prototype; a live system stores it on the server.</li></ul><b>Guidance for choosing a featured property and what to show</b><ul><li>Pick a live property with at least 7 days to the auction, a latest verified site visit, real photographs, a discount of 10% or more to market value and an AI score of 70 or more.</li><li>Prefer properties that match the slide: an NRI-friendly flat for the NRI slide, a high-discount property for the “what is it worth” slide, a property with a completed report for the “unknowns” slide.</li><li>Features show the short title, locality, reserve price and days left. Nothing else is shown until a visitor unlocks the property. Never feature a property you have not checked, and unfeature it when the auction ends.</li></ul></div>'+
 '<div id="cars">'+BA_CAR.map(function(d){var o=O[d.id]||{},t=o.title||d.title;return '<div class="sc" style="padding:16px;margin:14px 0" data-c="'+d.id+'"><div style="display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;align-items:center"><b>Slide '+d.id+' · '+esc(d.who)+'</b><label style="display:flex;gap:6px;align-items:center"><input type="checkbox" data-hide'+(o.hide?'':' checked')+'> Show on home page</label></div>'+
 '<div class="two" style="gap:14px;grid-template-columns:200px 1fr;margin-top:10px"><div><div style="aspect-ratio:1200/380;background:#F6F6F8;border:1px solid var(--line);border-radius:10px;overflow:hidden;display:flex;align-items:center;justify-content:center;font-size:12px;color:var(--mute);text-align:center">'+(o.img?'<img src="'+o.img+'" alt="" style="width:100%;height:100%;object-fit:cover">':'Default illustration')+'</div><label class="btn out sm" style="cursor:pointer;margin-top:8px;display:inline-block">Upload picture<input type="file" accept="image/jpeg,image/png,image/webp" data-img hidden></label>'+(o.img?' <button class="btn out sm" data-rimg>Use default</button>':'')+'</div>'+
 '<div class="form" style="max-width:none"><label>Heading<input data-f="title" value="'+esc(t)+'" maxlength="80"></label><label>The problem<textarea data-f="prob" rows="2" maxlength="220">'+esc(o.prob||d.prob)+'</textarea></label><label>How we solve it<textarea data-f="sol" rows="2" maxlength="260">'+esc(o.sol||d.sol)+'</textarea></label><div class="two" style="gap:10px;grid-template-columns:1fr 1fr"><label>Button text<input data-f="cta" value="'+esc(o.cta||d.cta)+'" maxlength="40"></label><label>Button goes to<select data-f="href">'+LINKS.map(function(l){var v=o.href||d.href;return '<option value="'+l[0]+'"'+(l[0]===v?' selected':'')+'>'+l[1]+'</option>'}).join('')+'</select></label></div><label>Featured property reference (optional)<input data-f="pid" value="'+esc(o.pid||'')+'" placeholder="e.g. CHN-10241" style="text-transform:uppercase"></label><div data-chk>'+(o.pid?chkHtml(o.pid):'')+'</div></div></div>'+
 '<div class="ac" style="margin-top:10px"><button class="btn sm" data-save>Save slide '+d.id+'</button> <button class="btn out sm" data-reset>Reset text</button></div></div>'}).join('')+'</div><div class="ac"><a class="btn out" href="home.html" target="_blank">Preview home page</a></div>');
 tb.oninput=function(e){var t=e.target;if(t.dataset.f==='pid'){var c=t.closest('[data-c]'),v=t.value.trim().toUpperCase();c.querySelector('[data-chk]').innerHTML=v.length>5?chkHtml(v):''}};
 tb.onchange=function(e){var t=e.target,c=t.closest('[data-c]');if(!c)return;var id=+c.dataset.c,O2=ov(),o=O2[id]=O2[id]||{};
  if(t.hasAttribute('data-hide')){o.hide=!t.checked;BA.jset('ba3_car',O2);ST.log((t.checked?'Showed':'Hid')+' carousel slide '+id);BA.toast(t.checked?'Slide shown':'Slide hidden');return}
  if(t.hasAttribute('data-img')&&t.files[0])img(t.files[0],function(u){o.img=u;try{BA.jset('ba3_car',O2)}catch(x){BA.toast('Browser storage is full. Try a smaller picture.');return}ST.log('Replaced picture on carousel slide '+id);BA.toast('Picture updated');window.ADM_CAR(tb)})};
 tb.onclick=function(e){var t=e.target.closest('button');if(!t)return;var c=t.closest('[data-c]');if(!c)return;var id=+c.dataset.c,O2=ov(),o=O2[id]=O2[id]||{};
  if(t.hasAttribute('data-rimg')){delete o.img;BA.jset('ba3_car',O2);ST.log('Restored default picture on slide '+id);window.ADM_CAR(tb)}
  else if(t.hasAttribute('data-reset')){var h=o.hide,im=o.img;O2[id]={hide:h,img:im};BA.jset('ba3_car',O2);ST.log('Reset text on slide '+id);window.ADM_CAR(tb)}
  else if(t.hasAttribute('data-save')){var f={};c.querySelectorAll('[data-f]').forEach(function(x){f[x.dataset.f]=x.value.trim()});
   if(f.title.length<5||f.prob.length<15||f.sol.length<15){BA.toast('Heading, problem and solution cannot be left short');return}
   if(f.pid){f.pid=f.pid.toUpperCase();var ck=checks(f.pid);if(ck.err||ck.hard){BA.toast(ck.err||'This property cannot be featured. Fix the items marked ✕.');c.querySelector('[data-chk]').innerHTML=chkHtml(f.pid);return}if(ck.warn)BA.toast('Saved with warnings. Check the items marked !')}
   o.title=f.title;o.prob=f.prob;o.sol=f.sol;o.cta=f.cta||undefined;o.href=f.href;o.pid=f.pid||undefined;BA.jset('ba3_car',O2);ST.log('Updated carousel slide '+id+(f.pid?' featuring '+f.pid:''));BA.toast('Slide '+id+' saved. It is live on the home page.')}}};
})();
